package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import static com.aliothmoon.maafw.once.BingNavigationFixture.*;
/** Complete strict synthetic metadata, not a task-presence-to-Ready conversion. */
public class TimedReturnSnapshotTest {
    static BingNavigationSnapshot.Result post(BingNavigationSnapshot.Ready original,long now){
        var shape=original.profile().shape();String w=RootReadOnlyAnimationGuardTest.w().replace("w=523 h=1000","w="+shape.width()+" h="+shape.height());
        String a=RootReadOnlyAnimationGuardTest.a().replaceAll("(?m)^.*topResumedActivity=.*\\n","");
        return BingNavigationSnapshot.parseTimedReturn(w,a,original.profile(),RootReadOnlyAnimationGuardTest.G,original,now,now);
    }
    static BingNavigationSnapshot.Result parse(String w,String a){return BingNavigationSnapshot.parseTimedReturn(w,a,PROFILE,RootReadOnlyAnimationGuardTest.G,TimedTaskGuardTest.original(),7000,7010);}
    @Test public void noGlobalTopNullOrOtherTasksDoesNotReplaceFullTemplateChain(){String a=RootReadOnlyAnimationGuardTest.a().replaceAll("(?m)^.*topResumedActivity=.*\\n","");for(String doc:new String[]{a,a+"topResumedActivity=null\n",a+"topResumedActivity=ActivityRecord{123 u0 other/.Activity t80}\ntopResumedActivity=ActivityRecord{456 u0 other/.Activity t81}\n"}){var r=parse(RootReadOnlyAnimationGuardTest.w(),doc);assertEquals(BingNavigationSnapshot.Status.READY,r.status());assertTrue(r.ready().sameSource(TimedTaskGuardTest.original()));assertTrue(r.ready().fresh(7010));}}
    @Test public void staleOriginalDoesNotBackdateTheNewReady(){var r=post(TimedTaskGuardTest.original(),9000);assertEquals(9000,r.ready().lower());assertTrue(r.ready().fresh(9000));assertFalse(r.ready().fresh(14001));assertFalse(TimedTaskGuardTest.original().fresh(9000));}
    @Test public void browserCannotBeTurnedIntoOriginalTemplateByBackExit(){var r=parse(TimedTaskGuardTest.browserWindows(),TimedTaskGuardTest.browserActivities());assertNotEquals(BingNavigationSnapshot.Status.READY,r.status());assertNull(r.ready());}
    @Test public void identityReplacementOrProfileMismatchRejects(){for(String w:new String[]{RootReadOnlyAnimationGuardTest.w().replace("Window{aaa","Window{aab"),RootReadOnlyAnimationGuardTest.w().replace("ActivityRecord{ddd","ActivityRecord{ddc"),RootReadOnlyAnimationGuardTest.w().replace("mOwnerUid=10073","mOwnerUid=10074"),RootReadOnlyAnimationGuardTest.w().replace("w=523 h=1000","w=523 h=999")})assertNotEquals(BingNavigationSnapshot.Status.READY,parse(w,RootReadOnlyAnimationGuardTest.a()).status());}
    @Test public void allOldDrawLifecycleTaskAndOwnerGatesStillRun(){for(String w:new String[]{RootReadOnlyAnimationGuardTest.w().replace("HAS_DRAWN","DRAW_PENDING"),RootReadOnlyAnimationGuardTest.w().replace("mDrawState=HAS_DRAWN","missingDraw"),RootReadOnlyAnimationGuardTest.w().replace(RootReadOnlyAnimationGuardTest.ownWindow(),""),RootReadOnlyAnimationGuardTest.w()+window("other/.Overlay","1234",true)})assertNotEquals(BingNavigationSnapshot.Status.READY,parse(w,RootReadOnlyAnimationGuardTest.a()).status());
        for(String a:new String[]{RootReadOnlyAnimationGuardTest.a().replace("state=RESUMED","state=PAUSING"),RootReadOnlyAnimationGuardTest.a().replace("A=10073:com.microsoft.bing U=0","A=10074:com.microsoft.bing U=0"),RootReadOnlyAnimationGuardTest.a().replace("  * Task{abc #15","  * Task{abcd #15")})assertNotEquals(BingNavigationSnapshot.Status.READY,parse(RootReadOnlyAnimationGuardTest.w(),a).status());}
    @Test public void presentTaskProofIsInsufficientForThisPostReady(){String a=RootReadOnlyAnimationGuardTest.a().replace("state=RESUMED","state=PAUSING");assertTrue(TimedTaskGuardTest.parse(RootReadOnlyAnimationGuardTest.w(),a).matches(TimedTaskGuardTest.original(),6010));assertNotEquals(BingNavigationSnapshot.Status.READY,parse(RootReadOnlyAnimationGuardTest.w(),a).status());}
    @Test public void legacyParserKeepsItsGlobalTopStoppingPolicy(){String a=RootReadOnlyAnimationGuardTest.a().replaceAll("(?m)^.*topResumedActivity=.*\\n","");assertEquals(BingNavigationSnapshot.FirstGate.TOP_RESUMED_COUNT,RootReadOnlyAnimationGuardTest.r(RootReadOnlyAnimationGuardTest.w(),a).firstGate());assertEquals(BingNavigationSnapshot.Status.READY,parse(RootReadOnlyAnimationGuardTest.w(),a).status());}
    @Test public void missingNullWrongAnchorOrOldPairDoesNotIssueReady(){assertNull(BingNavigationSnapshot.parseTimedReturn(null,null,PROFILE,RootReadOnlyAnimationGuardTest.G,TimedTaskGuardTest.original(),7000,7010).ready());assertNull(BingNavigationSnapshot.parseTimedReturn(RootReadOnlyAnimationGuardTest.w(),RootReadOnlyAnimationGuardTest.a(),PROFILE,RootReadOnlyAnimationGuardTest.G,null,7000,7010).ready());assertNull(BingNavigationSnapshot.parseTimedReturn(RootReadOnlyAnimationGuardTest.w(),RootReadOnlyAnimationGuardTest.a(),PROFILE,RootReadOnlyAnimationGuardTest.G,TimedTaskGuardTest.original(),0,7010).ready());}
}
